from ub import *
UNIT = mkunit("u111",
 ["menulis **kalimat topik** (topic sentence) yang jelas",
  "menambahkan **kalimat pendukung** dan **contoh**",
  "memakai **kata penghubung urutan dan alasan** (first, then, because, for example)",
  "menulis **penutup** dan memeriksa **kesatuan** paragraf"],
 [intro("Paragraf yang baik membahas **satu gagasan**. Paragraf memiliki kalimat topik, beberapa kalimat pendukung, dan kalimat penutup. Pelajari polanya, lalu latih menyusun serta memeriksanya."),
  gram("1. Struktur paragraf",
   table=[["Bagian", "Fungsi", "Contoh"],
          ["**Kalimat topik**", "menyatakan gagasan utama", "[[I enjoy my weekends.]]"],
          ["**Kalimat pendukung**", "menjelaskan alasan atau detail", "[[I can sleep late and relax.]]"],
          ["**Contoh**", "memperjelas", "[[For example, I read a book in the morning.]]"],
          ["**Penutup**", "menegaskan gagasan utama", "[[That is why weekends are my favourite days.]]"]],
   examples=[("[[I enjoy my weekends. I can sleep late and relax. For example, I read a book in the morning. That is why weekends are my favourite days.]]", "Aku menikmati akhir pekanku. Aku bisa tidur lebih lama dan bersantai. Misalnya, aku membaca buku di pagi hari. Itulah sebabnya akhir pekan adalah hari favoritku.")]),
  gram("2. Kata penghubung untuk paragraf",
   table=[["Fungsi", "Kata", "Contoh"],
          ["Urutan", "[[First]], [[Next]], [[Then]], [[Finally]]", "[[First, I wake up. Then I take a shower.]]"],
          ["Alasan", "[[because]], [[so]]", "[[I stay home because it is raining.]]"],
          ["Contoh", "[[for example]], [[such as]]", "[[I like fruit, such as mangoes.]]"],
          ["Tambahan", "[[also]], [[and]], [[too]]", "[[I also like to swim.]]"],
          ["Lawan", "[[but]], [[however]]", "[[I like tea, but I do not like coffee.]]"],
          ["Penutup", "[[That is why]], [[In short]]", "[[That is why I love reading.]]"]]),
  gram("3. Kesatuan dan urutan",
   text="Semua kalimat harus mendukung kalimat topik. Kalimat yang tidak berhubungan **merusak kesatuan**. Susun dari umum ke detail, atau berurutan menurut waktu.",
   table=[["Cek", "Pertanyaan"],
          ["Kesatuan", "Apakah setiap kalimat mendukung gagasan utama?"],
          ["Urutan", "Apakah urutan waktu atau alasan masuk akal?"],
          ["Penghubung", "Apakah kalimat tersambung dengan kata penghubung?"],
          ["Tata bahasa", "Apakah tense, tanda baca, dan ejaan benar?"]]),
  tip("Mulai dengan satu gagasan", text="Sebelum menulis, tulis satu kalimat: *Aku ingin menjelaskan bahwa ...*. Itulah kalimat topikmu. Jika sulit, berarti gagasanmu terlalu luas."),
  summary(["Paragraf = kalimat topik + pendukung + contoh + penutup.", "Satu paragraf = satu gagasan.", "Pakai penghubung: first, then, because, for example, that is why.", "Periksa: kesatuan, urutan, penghubung, tata bahasa."])],
 [], [])
